INSERT INTO todos (id, title, contents, weather, user_id, created_at, modified_at) VALUES
                                                                                       (1, '기획 문서 작성', '요구사항을 정리한다.', 'Cloudy and Cool', 2, '2026-09-01 09:30:00', '2026-09-01 09:30:00'),
                                                                                       (2, 'API 명세 검토', 'Swagger API를 점검한다.', 'Sunny and Cool', 3, '2026-09-01 10:00:00', '2026-09-01 12:00:00'),
                                                                                       (3, 'JPQL 조건 검색', '날씨와 기간 조건을 확인한다.', 'Cloudy and Cool', 4, '2026-09-01 11:00:00', '2026-09-01 15:00:00'),
                                                                                       (4, '댓글 N+1 점검', 'EntityGraph 결과를 확인한다.', 'Heavy Thunderstorms', 5, '2026-09-01 13:00:00', '2026-09-01 18:00:00'),
                                                                                       (5, 'QueryDSL 설정', 'Q 타입 생성 여부를 확인한다.', 'Sunny and Cool', 6, '2026-09-01 14:00:00', '2026-09-02 08:00:00'),
                                                                                       (6, '보안 정책 확인', 'USER와 ADMIN 권한을 분리한다.', 'Cloudy and Cool', 7, '2026-09-02 08:30:00', '2026-09-02 09:00:00'),
                                                                                       (7, '트랜잭션 로그', '독립 트랜잭션을 설계한다.', 'Heavy Thunderstorms', 8, '2026-09-02 09:00:00', '2026-09-02 09:30:00'),
                                                                                       (8, '테스트 데이터 준비', '조회 조건용 더미 데이터를 확인한다.', 'Cloudy and Cool', 9, '2026-09-02 09:30:00', '2026-09-02 10:00:00'),
                                                                                       (9, 'README 초안 작성', '실행 방법을 정리한다.', 'Sunny and Cool', 10, '2026-09-02 10:00:00', '2026-09-02 10:30:00'),
                                                                                       (10, '관리자 로그 검증', 'AOP 로그 순서를 확인한다.', 'Heavy Thunderstorms', 11, '2026-09-02 10:30:00', '2026-09-02 11:00:00'),
                                                                                       (11, '날씨 검색 검증', 'Cloudy and Cool 조건을 조회한다.', 'Cloudy and Cool', 12, '2026-09-02 11:00:00', '2026-09-02 11:30:00'),
                                                                                       (12, '페이징 경계 확인', '두 번째 페이지를 확인한다.', 'Sunny and Cool', 2, '2026-09-02 11:30:00', '2026-09-02 12:00:00'),
                                                                                       (13, '담당자 목록 점검', 'Manager 목록을 확인한다.', 'Heavy Thunderstorms', 3, '2026-09-02 12:00:00', '2026-09-02 12:30:00'),
                                                                                       (14, '댓글 목록 점검', 'Comment 목록을 확인한다.', 'Cloudy and Cool', 4, '2026-09-02 12:30:00', '2026-09-02 13:00:00'),
                                                                                       (15, '최종 회귀 테스트', '필수 API를 다시 호출한다.', 'Sunny and Cool', 5, '2026-09-02 13:00:00', '2026-09-02 13:30:00');
